<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, type Comment, type Milestone, type NowData } from '../api/client'
const data=ref<NowData>({diary:{id:'',entryDate:'',content:'',secret:false,commentable:false},moods:[],bodies:[],tasks:[]});const comments=ref<Comment[]>([]);const milestones=ref<Milestone[]>([]);const loading=ref(true);const error=ref('');const comment=ref('')
async function load(){loading.value=true;try{data.value=await api.visibleToday();if(data.value.diary.id){const [commentResult,milestoneResult]=await Promise.all([api.comments('diary',data.value.diary.id),api.milestones('diary',data.value.diary.id)]);comments.value=commentResult.items;milestones.value=milestoneResult.items}else{comments.value=[];milestones.value=[]}}catch(e){error.value=e instanceof Error?e.message:'无法读取内容'}finally{loading.value=false}}
async function addComment(){if(!data.value.diary.id)return;try{await api.addComment('diary',data.value.diary.id,comment.value);comment.value=''}catch(e){error.value=e instanceof Error?e.message:'评论失败'}}
onMounted(load)
</script>
<template><main class="now-page reader-page"><header class="now-header"><div><p class="eyebrow">READER / FILTERED VIEW</p><h1>今日</h1></div><button @click="load">刷新</button></header><p v-if="error" class="error">{{error}}</p><p v-if="loading" class="empty">正在按阅读权限筛选内容…</p><div v-else class="now-grid"><section class="stack"><article class="panel diary"><header><h2>日记</h2><small>{{data.diary.entryDate}}</small></header><p v-if="!data.diary.id" class="empty">今日没有你可访问的日记。</p><pre v-else class="reader-diary">{{data.diary.content}}</pre><section v-if="milestones.length" class="reader-list"><b>里程碑</b><p v-for="item in milestones" :key="item.id">✦ {{item.description}}</p></section><section v-if="comments.length" class="reader-list"><b>评论</b><p v-for="item in comments" :key="item.id">{{item.content}}</p></section><form v-if="data.diary.id && data.diary.commentable" class="compact" @submit.prevent="addComment"><input v-model.trim="comment" placeholder="写下评论" required/><button>发送</button></form></article><article class="panel"><header><h2>心情记录</h2><small>{{data.moods.length}} 条可见</small></header><p v-if="!data.moods.length" class="empty">没有可访问记录。</p><ul v-else class="reader-list"><li v-for="item in data.moods" :key="item.id"><b>{{item.tags.map(x=>x.emoji).join(' ')}}</b><span>{{item.note}}</span></li></ul></article></section><section class="panel tasks"><header><h2>今日任务</h2><small>{{data.tasks.length}} 项可见</small></header><ul><li v-for="task in data.tasks" :key="task.id" :class="{done:task.done}"><input :checked="task.done" type="checkbox" disabled/><div><b>{{task.title}}</b><small v-if="task.description">{{task.description}}</small></div></li><li v-if="!data.tasks.length" class="empty">没有可访问任务。</li></ul></section></div></main></template>